    Optional<Customer> find(long id) throws DataAccessException;
}
final class JdbcCustomerDAO implements CustomerDAO {
    private final DataSource ds;                  // injected pool, never per call
    public Optional<Customer> find(long id) throws DataAccessException {
        String sql = "SELECT id, name, version FROM customer WHERE id = ?";
        try (Connection c = ds.getConnection(); PreparedStatement ps = c.prepareStatement(sql)) {
            ps.setLong(1, id);
            try (ResultSet rs = ps.executeQuery()) { return rs.next() ? Optional.of(map(rs)) : Optional.empty(); }
        } catch (SQLException e) { throw new DataAccessException("find customer", e); }
    }
}

