@Repository
public class CustomerDao {                     // thin: SQL + mapping only
    private final JdbcClient jdbc;
    public CustomerDao(JdbcClient jdbc) { this.jdbc = jdbc; }

    public Optional<Customer> find(long id) {
        return jdbc.sql("SELECT id, name, version FROM customer WHERE id = :id")
                   .param("id", id)
                   .query((rs, n) -> new Customer(rs.getLong("id"), rs.getString("name")))
                   .optional();                // no Connection/ResultSet handling left
    }
}

public class CustomerDao {
    @PersistenceContext private EntityManager em;      // container-managed

    public Optional<CustomerEntity> find(long id) {
        return Optional.ofNullable(em.find(CustomerEntity.class, id));
    }
    public List<CustomerEntity> byEmail(String email) {
        return em.createQuery("select c from CustomerEntity c where c.email = :e",
                             CustomerEntity.class)
                 .setParameter("e", email).getResultList();
    }
}
